/// <summary>
///     Extends method setSalesTableData
/// </summary>
protected void setSalesTableData()
{
    SalesTable locSalesTable;

    next setSalesTableData();

    locSalesTable = axSalesTable.salesTable();

    //info(strFmt("NetPG1: %1, NetPG2: %2", locSalesTable.AVANetPG1, locSalesTable.AVANetPG2));

    axSalesTable.avaParmNetPG1(locSalesTable.AVANetPG1);
    axSalesTable.avaParmNetPG2(locSalesTable.AVANetPG2);

    axSalesTable.parmAvaKCS_FreightCostStatus(purchTable.KCS_FreightCostStatus);
    axSalesTable.parmAvaKCS_POC_CarriageFree(purchTable.KCS_POC_CarriageFree);
    axSalesTable.parmAvaKCS_FreightCalculation(purchTable.KCS_FreightCalculation);
    axSalesTable.parmAvaKCS_FreightChargeFree(purchTable.KCS_FreightChargeFree);
    axSalesTable.parmAvaKCS_FreightCosts(purchTable.KCS_FreightCosts);
    axSalesTable.parmAVADlvResponsible(purchTable.AVADlvResponsible);

    axSalesTable.parmAVAShipCarrierDeliveryContact(purchTable.AVAShipCarrierDeliveryContact);
    axSalesTable.parmNDX_ShipCarrierDeliveryEmail(purchTable.NDX_ShipCarrierDeliveryEmail);
    axSalesTable.parmNDX_ShipCarrierDeliveryPhone(purchTable.NDX_ShipCarrierDeliveryPhone);
    axSalesTable.parmAVAShipCarrierDeliveryMobile(purchTable.AVAShipCarrierDeliveryMobile);
    axSalesTable.parmInventSiteId(purchTable.InventSiteId);
}
